    "confidence": 0.35,
    "verification": {
      "kind": "trace_check",
      "params": {
        "signal": "traces",
        "filter_expression": "service.name = 'orders' AND name = 'POST /orders http send' AND http.status_code = 502"
      },
      "expected": {
        "op": "gt",
        "value": 0,
        "description": "There exist orders spans returning 502 for POST /orders during the incident window, confirming orders as a contributing failure point"
      }
    }
